const sanitizeSections = (secs: Section[]): Section[] => {
  console.log("[Builder Debug] Memulai sanitasi data sections. Jumlah input:", secs.length);
  let sorted = [...secs].sort((a, b) => a.order - b.order);
  let headerIdx = sorted.findIndex(s => s.type === 'HEADER');

  let headerSection: Section;
  if (headerIdx === -1) {
    headerSection = {
      id: 'global-header',
      type: 'HEADER',
      config: {
        bgColor: 'rgba(255, 255, 255, 0.9)',
        textColor: '#18181B',
        layout: 'horizontal',
        gap: 16,
        align: 'center',
        paddingTop: 16,
        paddingBottom: 16,
        paddingLeft: 40,
        paddingRight: 40
      },
      elements: [],
      order: -1,
      isActive: true
    };
    console.log("[Builder Debug] Header tidak ditemukan, menginjeksi header bawaan baru.");
  } else {
    headerSection = { ...sorted[headerIdx] };
    sorted.splice(headerIdx, 1);
  }

  // Pastikan BRANDING, MENU, CART ada dalam urutan kaku (branding, menu, cart)
  const elements = headerSection.elements || [];
  const branding = elements.find(el => el.type === 'BRANDING') || {
    id: 'h-el-branding',
    type: 'BRANDING',
    config: { fontSize: 16, textColor: '#18181B', align: 'left' },
    order: 0
  };
  const menu = elements.find(el => el.type === 'MENU') || {
    id: 'h-el-menu',
    type: 'MENU',
    config: { fontSize: 13, textColor: '#18181B', align: 'center', fontFamily: 'Inter', hiddenMenus: [] },
    order: 1
  };
  const cart = elements.find(el => el.type === 'CART') || {
    id: 'h-el-cart',
    type: 'CART',
    config: { text: 'Keranjang', bgColor: '#18181B', textColor: '#FFFFFF', borderRadius: 8, align: 'right' },
    order: 2
  };

  // Kunci field order & id
  branding.order = 0;
  menu.order = 1;
  cart.order = 2;

  headerSection.elements = [branding, menu, cart];
  headerSection.order = -1;

  console.log("[Builder Debug] Selesai melakukan sanitasi data sections. Header dikunci dengan 3 elemen kaku.");
  return [headerSection, ...sorted];
}


interface DraggableReorderItemProps {
  value: any;
  onDragStart?: (itemId: string) => void;
  onDragEnd?: () => void;
  className?: string;
  onClick?: (e: React.MouseEvent) => void;
  children: (dragControls: ReturnType<typeof useDragControls>) => React.ReactNode;
}

function DraggableReorderItem({ value, onDragStart, onDragEnd, className, onClick, children }: DraggableReorderItemProps) {
  const dragControls = useDragControls();
  return (
    <Reorder.Item
      value={value}
      drag="y"
      dragListener={false}
      dragControls={dragControls}
      onDragStart={() => {
        console.log('[Builder Drag] Drag started for item:', value?.id || value);
        if (onDragStart) onDragStart(value?.id || String(value));
      }}
      onDragEnd={() => {
        console.log('[Builder Drag] Drag ended for item:', value?.id || value);
        if (onDragEnd) onDragEnd();
      }}
      className={className}
      onClick={onClick}
    >
      {children(dragControls)}
    </Reorder.Item>
  );
}

interface MoveControlsProps {
  canMoveUp: boolean;
  canMoveDown: boolean;
  onMoveUp: (e: React.MouseEvent) => void;
  onMoveDown: (e: React.MouseEvent) => void;
}

function MoveControls({ canMoveUp, canMoveDown, onMoveUp, onMoveDown }: MoveControlsProps) {
  return (
    <div className="flex flex-col shrink-0 leading-none opacity-0 group-hover:opacity-100 transition-opacity">
      <button
        type="button"
        onClick={onMoveUp}
        disabled={!canMoveUp}
        className={`p-0 rounded ${canMoveUp ? "text-slate-300 hover:text-slate-100" : "text-slate-700 cursor-not-allowed"}`}
      >
        <ChevronUp className="w-3 h-3" strokeWidth={2.25} />
      </button>
      <button
        type="button"
        onClick={onMoveDown}
        disabled={!canMoveDown}
        className={`p-0 rounded ${canMoveDown ? "text-slate-300 hover:text-slate-100" : "text-slate-700 cursor-not-allowed"}`}
      >
        <ChevronDown className="w-3 h-3" strokeWidth={2.25} />
      </button>
    </div>
  );
}

const parseUnitAndValue = (rawVal: any, defaultVal = 0) => {
  if (rawVal === undefined || rawVal === null || rawVal === '') {
    return { val: defaultVal, unit: 'px' as const, customStr: '', isCustom: false, isDefault: true };
  }
  if (typeof rawVal === 'number') {
    return { val: rawVal, unit: 'px' as const, customStr: '', isCustom: false, isDefault: false };
  }
  const str = String(rawVal).trim();

  const match = str.match(/^([\d.-]+)(px|vw|%|rem|em|vh)$/);
  if (match) {
    const num = parseFloat(match[1]);
    const unit = match[2];
    if (unit === 'px' || unit === 'vw' || unit === '%' || unit === 'em' || unit === 'rem' || unit === 'vh') {
      return { val: num, unit: unit as 'px' | 'vw' | '%' | 'em' | 'rem' | 'vh', customStr: '', isCustom: false, isDefault: false };
    }
  }

  if (/^[\d.-]+$/.test(str)) {
    return { val: parseFloat(str), unit: 'px' as const, customStr: '', isCustom: false, isDefault: false };
  }

  return { val: defaultVal, unit: 'custom' as const, customStr: str, isCustom: true, isDefault: false };
};

interface UnitControlProps {
  label: string;
  value: any;
  onChange: (val: any) => void;
  min?: number;
  max?: number;
  defaultValue?: number;
  fieldKey: string;
  activeDropdown: { field: string; elementId?: string } | null;
  setActiveDropdown: (state: { field: string; elementId?: string } | null) => void;
  elementId?: string;
}

function UnitControl({
  label,
  value,
  onChange,
  min = 0,
  max = 1000,
  defaultValue = 0,
  fieldKey,
  activeDropdown,
  setActiveDropdown,
  elementId
}: UnitControlProps) {
  const parsed = parseUnitAndValue(value, defaultValue);
  const dropdownOpen = activeDropdown?.field === fieldKey && activeDropdown?.elementId === elementId;

  const handleUnitSelect = (newUnit: 'px' | 'vw' | '%' | 'custom') => {
    setActiveDropdown(null);
    console.log(`[UnitControl] Unit diubah ke: ${newUnit} untuk field: ${fieldKey}`);
    if (newUnit === 'custom') {
      onChange(parsed.unit === 'custom' ? parsed.customStr : `${parsed.val}${parsed.unit === 'px' ? '' : parsed.unit}`);
    } else {
      onChange(newUnit === 'px' ? parsed.val : `${parsed.val}${newUnit}`);
    }
  };

  return (
    <div className="space-y-2 py-1">
      <div className="flex items-center justify-between">
        <span className="text-[10px] font-bold text-zinc-400 uppercase tracking-wide">{label}</span>

        <div className="relative">
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              if (dropdownOpen) {
                setActiveDropdown(null);
              } else {
                setActiveDropdown({ field: fieldKey, elementId });
              }
            }}
            className="flex items-center gap-1 text-[9px] text-zinc-500 hover:text-white font-black bg-zinc-900 border border-zinc-800 rounded px-1.5 py-0.5 transition-all select-none cursor-pointer"
          >
            <span>{parsed.unit === 'custom' ? '✏️ Custom' : parsed.unit}</span>
            <ChevronDown className="w-2.5 h-2.5 opacity-60" />
          </button>

          {dropdownOpen && (
            <div className="absolute right-0 mt-1 w-28 bg-zinc-900 border border-zinc-800 rounded-lg shadow-2xl overflow-hidden py-1 z-[1000] animate-in fade-in slide-in-from-top-1 duration-150">
              {(['px', 'vw', '%', 'custom'] as const).map((u) => (
                <button
                  key={u}
                  type="button"
                  onClick={() => handleUnitSelect(u)}
                  className={`w-full text-left text-[10px] font-bold px-3 py-1.5 hover:bg-zinc-800 hover:text-white transition-all flex items-center justify-between ${parsed.unit === u ? 'text-blue-400 bg-zinc-850' : 'text-zinc-400'}`}
                >
                  <span>{u === 'custom' ? '✏️ Custom' : u}</span>
                  {parsed.unit === u && <span className="w-1 h-1 rounded-full bg-blue-400" />}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {parsed.unit === 'custom' ? (
        <div className="flex gap-2">
          <input
            type="text"
            value={parsed.customStr}
            placeholder="Contoh: calc(100vh - 40px), auto"
            onChange={(e) => {
              onChange(e.target.value);
              console.log(`[UnitControl] Custom value diubah ke: ${e.target.value} untuk field: ${fieldKey}`);
            }}
            className="flex-1 h-8 text-xs px-2.5 bg-zinc-950 text-zinc-100 border border-zinc-800 rounded focus:border-zinc-700 outline-none placeholder:text-zinc-700 font-bold"
          />
        </div>
      ) : (
        <div className="flex items-center gap-3">
          <input
            type="range"
            min={min}
            max={max}
            value={parsed.val}
            onChange={(e) => {
              const num = Number(e.target.value);
              onChange(parsed.unit === 'px' ? num : `${num}${parsed.unit}`);
              console.log(`[UnitControl] Slider diubah ke: ${num} dengan unit: ${parsed.unit} untuk field: ${fieldKey}`);
            }}
            className="flex-1 accent-white bg-zinc-800 h-1 rounded-lg appearance-none cursor-pointer"
          />
          <input
            type="number"
            value={parsed.isDefault ? '' : parsed.val}
            placeholder={String(defaultValue)}
            onChange={(e) => {
              const raw = e.target.value;
              console.log(`[UnitControl Debug] Input number raw untuk field: ${fieldKey} ke: "${raw}"`);
              if (raw === '') {
                console.log(`[UnitControl Debug] Field ${fieldKey} kosong, mengembalikan ke default (undefined)`);
                onChange(undefined);
                return;
              }
              const num = Number(raw);
              onChange(parsed.unit === 'px' ? num : `${num}${parsed.unit}`);
              console.log(`[UnitControl Debug] Field ${fieldKey} diubah ke: ${num}${parsed.unit === 'px' ? '' : parsed.unit}`);
            }}
            className={`w-14 h-7 text-center text-xs font-bold bg-[#1a1a1f] border border-zinc-800 rounded focus:border-zinc-700 outline-none transition-all ${parsed.isDefault ? 'text-zinc-100/40 placeholder:text-zinc-100/40' : 'text-zinc-100'}`}
          />
        </div>
      )}
    </div>
  );
}


