                                              const layouts: string[] = [];
                                              for (let c = 2; c <= Math.min(cols, 6); c++) {
                                                for (let r = 2; r <= Math.min(Math.ceil(cols / c) + 1, 5); r++) {
                                                  if (c * r >= cols && !layouts.includes(`${c}x${r}`)) {
                                                    layouts.push(`${c}x${r}`);
                                                  }
                                                }
                                              }
                                              return layouts.map(l => <option key={l} value={l}>{l}</option>);
